DROP TABLE IF EXISTS `application_transition_logs`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `application_transition_logs` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `entity_type` enum('APPLICATION','JOB_REQUISITION','JOB_POSTING') NOT NULL,
  `entity_id` bigint NOT NULL,
  `actor_id` bigint DEFAULT NULL,
  `actor_role` varchar(50) DEFAULT NULL,
  `action` varchar(60) NOT NULL,
  `from_status` varchar(50) DEFAULT NULL,
  `to_status` varchar(50) NOT NULL,
  `comment` text,
  `request_id` varchar(100) DEFAULT NULL,
  `idempotency_key` varchar(100) NOT NULL,
  `occurred_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_transition_idempotency_key` (`idempotency_key`),
  KEY `fk_transition_actor` (`actor_id`),
  KEY `idx_transition_entity_timeline` (`entity_type`,`entity_id`,`occurred_at`,`id`),
  KEY `idx_transition_request_id` (`request_id`),
  CONSTRAINT `fk_transition_actor` FOREIGN KEY (`actor_id`) REFERENCES `users` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=81 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

