DROP TABLE IF EXISTS `applications`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `applications` (
  `fit_score` int DEFAULT NULL,
  `fraud_flagged` bit(1) NOT NULL,
  `created_at` datetime(6) DEFAULT NULL,
  `id` bigint NOT NULL AUTO_INCREMENT,
  `job_posting_id` bigint NOT NULL,
  `updated_at` datetime(6) DEFAULT NULL,
  `cccd_url` varchar(255) DEFAULT NULL,
  `cv_url` varchar(255) DEFAULT NULL,
  `email` varchar(255) NOT NULL,
  `extracted_data` json DEFAULT NULL,
  `full_name` varchar(255) NOT NULL,
  `phone` varchar(255) NOT NULL,
  `raw_cv_text` text,
  `approval_status` enum('PENDING_HR_CV_REVIEW','PENDING_TECH_CV_REVIEW','PENDING_INTERVIEW_1','PENDING_INTERVIEW_2','PENDING_HR_OFFER','PENDING_OFFER_APPROVAL','OFFER_INTERNALLY_APPROVED','OFFER_SENT','OFFER_ACCEPTED','REJECTED','TALENT_POOL','WITHDRAWN','OFFER_DECLINED','OFFER_EXPIRED','OFFER_REVOKED') NOT NULL,
  `is_priority` bit(1) NOT NULL,
  `needs_verification` bit(1) NOT NULL,
  `hr_review_feedback` text,
  `hr_reviewer` varchar(150) DEFAULT NULL,
  `interview1feedback` text,
  `interview1reviewer` varchar(150) DEFAULT NULL,
  `interview2feedback` text,
  `interview2reviewer` varchar(150) DEFAULT NULL,
  `offer_details` text,
  `rejection_reason` text,
  `rejector_name` varchar(150) DEFAULT NULL,
  `tech_review_feedback` text,
  `tech_reviewer` varchar(150) DEFAULT NULL,
  `version` bigint NOT NULL DEFAULT '0',
  `first_viewed_at` datetime(6) DEFAULT NULL,
  `viewed_by` bigint DEFAULT NULL,
  `normalized_email` varchar(255) GENERATED ALWAYS AS (lower(trim(`email`))) STORED,
  `normalized_phone` varchar(30) GENERATED ALWAYS AS (regexp_replace(`phone`,_utf8mb4'[^0-9]',_utf8mb4'')) STORED,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_application_posting_email` (`job_posting_id`,`normalized_email`),
  UNIQUE KEY `uk_application_posting_phone` (`job_posting_id`,`normalized_phone`),
  KEY `fk_application_viewed_by` (`viewed_by`),
  CONSTRAINT `fk_application_viewed_by` FOREIGN KEY (`viewed_by`) REFERENCES `users` (`id`),
  CONSTRAINT `FKrisuup1r36sqpf7hp1b6v1jjg` FOREIGN KEY (`job_posting_id`) REFERENCES `job_postings` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=46 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

