DROP TABLE IF EXISTS `approval_requests`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `approval_requests` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `entity_type` enum('JOB_REQUISITION','APPLICATION_TECH_REVIEW','OFFER') NOT NULL,
  `entity_id` bigint NOT NULL,
  `entity_version` bigint NOT NULL,
  `policy_id` bigint NOT NULL,
  `status` enum('OPEN','APPROVED','RETURNED','REJECTED','CANCELLED') NOT NULL,
  `requested_by` bigint NOT NULL,
  `submission_key` varchar(120) NOT NULL,
  `cancel_reason` varchar(500) DEFAULT NULL,
  `created_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `updated_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `completed_at` datetime(6) DEFAULT NULL,
  `row_version` bigint NOT NULL DEFAULT '0',
  `open_entity_key` varchar(160) GENERATED ALWAYS AS ((case when (`status` = _utf8mb4'OPEN') then concat(`entity_type`,_utf8mb4':',`entity_id`) else NULL end)) STORED,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_approval_request_submission` (`submission_key`),
  UNIQUE KEY `uk_approval_request_open_entity` (`open_entity_key`),
  KEY `fk_approval_request_policy` (`policy_id`),
  KEY `fk_approval_request_requested_by` (`requested_by`),
