INSERT INTO `employee_requests` VALUES (1,'2026-08-25 09:09:50.290190','2026-08-26','Đồng ý duyệt','ádsada','NORMAL_LEAVE','2026-08-25','APPROVED','2026-08-25 09:11:16.571404',2,3),(2,'2026-08-25 09:52:53.512893','2026-08-27','Đồng ý duyệt','đsdas','NORMAL_LEAVE','2026-08-26','APPROVED','2026-08-25 09:56:57.219800',2,3),(3,'2026-09-16 19:52:28.000000','2026-09-20',NULL,'Khám sức khỏe định kỳ theo lịch hẹn của bệnh viện.','NORMAL_LEAVE','2026-09-20','PENDING','2026-09-17 19:52:28.000000',8,7),(4,'2026-09-15 19:52:28.000000','2026-09-18','Đã xác nhận không ảnh hưởng lịch họp của phòng.','Làm việc tại nhà để tập trung hoàn thiện kế hoạch truyền thông quý mới.','SPECIAL_WFH_LEAVE','2026-09-18','APPROVED','2026-09-17 19:52:28.000000',11,12),(5,'2026-09-15 19:52:28.000000','2026-09-17','Được duyệt làm thêm tối đa ba giờ.','Hoàn thành báo cáo tài chính và đối soát số liệu trước kỳ chốt tháng.','OVERTIME','2026-09-17','APPROVED','2026-09-17 19:52:28.000000',15,13),(6,'2026-09-16 19:52:28.000000','2026-09-22',NULL,'Giải quyết công việc gia đình vào buổi chiều và đã bàn giao đầu việc.','HALF_DAY_LEAVE','2026-09-22','PENDING','2026-09-17 19:52:28.000000',5,16),(7,'2026-09-16 19:52:28.000000','2026-09-26',NULL,'Nghỉ phép năm để về quê thăm gia đình theo kế hoạch cá nhân.','NORMAL_LEAVE','2026-09-25','PENDING','2026-09-17 19:52:28.000000',5,17),(8,'2026-09-14 19:52:28.000000','2026-09-19','Bảo đảm tham gia đầy đủ các cuộc họp sản phẩm.','Làm việc từ xa để tham gia chuỗi phỏng vấn người dùng trực tuyến.','SPECIAL_WFH_LEAVE','2026-09-19','APPROVED','2026-09-17 19:52:28.000000',5,18),(9,'2026-09-15 19:52:28.000000','2026-09-17','Đã duyệt làm thêm hai giờ.','Rà soát gấp phụ lục hợp đồng đối tác trước thời hạn ký kết.','OVERTIME','2026-09-17','APPROVED','2026-09-17 19:52:28.000000',5,19),(10,'2026-09-16 19:52:28.000000','2026-09-30','Thời gian đề xuất trùng lịch kiểm kê văn phòng.','Xin nghỉ không lương để giải quyết thủ tục hành chính cá nhân.','UNPAID_LEAVE','2026-09-29','REJECTED'