INSERT INTO `group_messages` VALUES (1,'ss','2026-09-17 11:07:55.461470',_binary '\0',1,_binary '\0',_binary '\0',NULL,5),(2,'lll','2026-09-17 11:21:07.455662',_binary '\0',1,_binary '\0',_binary '\0',NULL,5),(3,'@AI-pl cho tôi số liệu nhân sự công ty','2026-09-17 11:37:58.722748',_binary '\0',1,_binary '\0',_binary '\0',NULL,1),(4,'Đã gọi hàm get_department_employees với department_id=1 để truy vấn nhân sự phòng Nhân sự.','2026-09-17 11:38:16.849810',_binary '\0',1,_binary '',_binary '\0',NULL,NULL),(5,'@AI-pl cho tôi số liệu tổng nhân viên','2026-09-17 13:38:40.859495',_binary '\0',1,_binary '\0',_binary '\0',NULL,1),(6,'Xin lỗi, với vai trò là Giám đốc Phòng ban Nhân sự, bạn chỉ có quyền xem thông tin chi tiết và số lượng nhân sự thuộc phòng ban của mình (Phòng Nhân sự). Bạn không có quyền truy cập số liệu tổng nhân viên toàn công ty.','2026-09-17 13:38:44.144255',_binary '\0',1,_binary '',_binary '\0',NULL,NULL),(7,'ok cho tôi xem','2026-09-17 13:38:56.485032',_binary '\0',1,_binary '\0',_binary '\0',NULL,1),(8,'@AI-pl cho tôi số liệu nhân sự công ty','2026-09-17 13:39:49.454509',_binary '\0',1,_binary '\0',_binary '\0',NULL,1),(9,'Xin lỗi, với vai trò là Giám đốc Phòng ban Nhân sự, bạn chỉ có quyền xem thông tin nhân sự thuộc phòng ban của mình (Phòng Nhân sự). Bạn không có quyền truy cập số liệu nhân sự của toàn công ty.','2026-09-17 13:39:50.937695',_binary '\0',1,_binary '',_binary '\0',NULL,NULL),(10,'cho tôi hỏi phòng nhân sự hiện đang có bao nhiêu người','2026-09-17 13:40:18.825467',_binary '\0',1,_binary '\0',_binary '\0',NULL,1),(11,'bạn đâu rồi','2026-09-17 13:42:28.032030',_binary '\0',1,_binary '\0',_binary '\0',NULL,1),(12,'@AI-pl cho tôi hỏi phòng nhân sự hiện đang có bao nhiêu người','2026-09-17 13:42:45.763390',_binary '\0',1,_binary '\0',_binary '\0',NULL,1),(13,'Dạ, theo dữ liệu hệ thống của phòng Nhân sự, hiện tại phòng mình có tổng cộng **3** nhân sự, cụ thể phân bổ theo các cấp bậc như sau:\n\n- **Giám đốc phòng ban:** 1 người\n- **Trưởng phòng:** 1 người\n- **Nhân viên:** 1 người','2026-09-17 13:42:47.868517',_binary '\0',1,_binary '',_binary '\0',NULL,NULL),(14,'@AI-pl số liệu lương phòng nhân sự hiện nay là bao nhiêu','2026-09-17 13:43:25.626834',_binary '\0',1,_binary '\0',_binary '\0',NULL,1),(15,'Hiện tại hệ thống ghi nhận chưa có báo cáo bảng lương nào được tạo cho phòng Nhân sự.','2026-09-17 13:43:27.382591',_binary '\0',1,_binary '',_binary '\0',NULL,NULL),(16,'@AI-pl bạn hãy set lương cho 1 nhân viên trong phòng nhân sự là mức lương người đó 5trieu và phụ cấp 500k','2026-09-17 13:44:21.399374',_binary '\0',1,_binary '\0',_binary '\0',NULL,1),(17,'Xin lỗi, chức năng thiết lập hoặc cập nhật bảng lương hiện chưa được tích hợp trong hệ thống hỗ trợ của tôi. Vui lòng thực hiện thao tác này trực tiếp trên phần mềm quản trị nhân sự hoặc liên hệ bộ phận Kế toán/C&B để được hỗ trợ.','2026-09-17 13:44:22.678371',_binary '\0',1,_binary '',_binary '\0',NULL,NULL),(18,'@AI-pv tại sao phòng nhân sự có 1+1=2','2026-09-17 13:44:57.577107',_binary '\0',1,_binary '\0',_binary '\0',1,1),(19,'Xin lỗi, tôi chỉ hỗ trợ các nghiệp vụ liên quan đến công ty và nhóm chat này','2026-09-17 13:44:58.670664',_binary '\0',1,_binary '',_binary '\0',1,NULL),(20,'@AI-pl  cho tôi thông tin cá nhân của Nguyễn Văn Giám Đốc','2026-09-17 13:46:24.166191',_binary '\0',1,_binary '\0',_binary '\0',NULL,5),(21,'Xin lỗi, hiện tại tôi chưa được tích hợp chức năng tra cứu thông tin chi tiết cá nhân của nhân sự trong hệ thống. Bạn có thể kiểm tra trực tiếp trên phần mềm quản trị nhân sự của công ty.','2026-09-17 13:46:25.556042',_binary '\0',1,_binary '',_binary '\0',NULL,NULL);
