INSERT INTO `job_postings` VALUES (_binary '\0',2,'2026-09-17 14:54:52.839019','2026-09-18 14:54:00.000000',9,'2026-09-17 14:54:00.000000','2026-09-17 14:56:20.511920','Là 1 chuyên viên phân tích dữ liệu dựa trên hình ảnh','Hồ Chí Minh','','Lương tháng 13','Có kinh nghiệm','chuyen-vien-phan-tich-1789631692835','EXPIRED','Chuyên viên phân tích','Nhân viên (Junior)','Toàn thời gian (Full-time)',1,4,'NHAN_VIEN',0,1,1),(_binary '\0',2,'2026-08-16 19:52:28.000000','2026-10-15 19:52:28.000000',10,'2026-09-24 19:52:28.000000','2026-09-22 14:01:19.034957','Phụ trách toàn bộ quy trình tìm nguồn, sàng lọc, phỏng vấn và chăm sóc ứng viên.','TP. Hồ Chí Minh','18.000.000 - 25.000.000 VNĐ','Thưởng hiệu suất, bảo hiểm đầy đủ, đào tạo chuyên môn và 14 ngày phép năm.','Có tối thiểu hai năm kinh nghiệm tuyển dụng, giao tiếp tốt và sử dụng thành thạo công cụ quản lý hồ sơ.','chuyen-vien-tuyen-dung-2026','PAUSED','Chuyên viên Tuyển dụng','Chuyên viên (Mid-level)','Toàn thời gian (Full-time)',1,5,'NHAN_VIEN',0,2,1),(_binary '',3,'2026-08-18 19:52:28.000000','2026-10-22 19:52:28.000000',11,'2026-09-24 19:52:28.000000','2026-09-17 19:52:28.000000','Phát triển API, tối ưu truy vấn dữ liệu và bảo đảm an toàn cho các dịch vụ backend.','TP. Hồ Chí Minh','25.000.000 - 38.000.000 VNĐ','Thiết bị làm việc hiện đại, ngân sách học tập, bảo hiểm sức khỏe và làm việc linh hoạt.','Thành thạo Java, Spring Boot, MySQL, REST API và có kinh nghiệm viết kiểm thử tự động.','lap-trinh-vien-backend-2026','OPEN','Lập trình viên Backend','Chuyên viên (Mid-level)','Linh hoạt (Hybrid)',2,6,'NHAN_VIEN',0,3,1),(_binary '',4,'2026-08-21 19:52:28.000000','2026-10-11 19:52:28.000000',12,'2026-09-24 19:52:28.000000','2026-09-17 19:52:28.000000','Tìm kiếm khách hàng doanh nghiệp, tư vấn giải pháp và theo dõi cơ hội bán hàng đến khi ký hợp đồng.','TP. Hồ Chí Minh','15.000.000 - 30.000.000 VNĐ','Hoa hồng theo doanh số, thưởng quý, phụ cấp gặp khách hàng và lộ trình thăng tiến rõ ràng.','Có kỹ năng giao tiếp, đàm phán, quản lý cơ hội bán hàng và chủ động đạt mục tiêu doanh số.','chuyen-vien-kinh-doanh-b2b-2026','OPEN','Chuyên viên Kinh doanh B2B','Nhân viên (Junior)','Toàn thời gian (Full-time)',3,7,'NHAN_VIEN',0,4,1),(_binary '',1,'2026-09-06 19:52:28.000000','2026-10-23 19:52:28.000000',13,'2026-09-24 19:52:28.000000','2026-09-17 19:52:28.000000','Quản lý nhóm bán hàng, huấn luyện nhân viên và chịu trách nhiệm về kế hoạch doanh thu khu vực.','TP. Hồ Chí Minh','28.000.000 - 40.000.000 VNĐ','Thưởng quản lý theo doanh số đội nhóm, phụ cấp công tác và chương trình đào tạo lãnh đạo.','Có tối thiểu ba năm quản lý bán hàng B2B, kỹ năng huấn luyện và lập kế hoạch doanh số.','truong-nhom-kinh-doanh-2026','OPEN','Trưởng nhóm Kinh doanh','Quản lý (Manager)','Toàn thời gian (Full-time)',3,8,'TRUONG_PHONG',0,5,1),(_binary '\0',2,'2026-08-23 19:52:28.000000','2026-10-17 19:52:28.000000',14,'2026-09-24 19:52:28.000000','2026-09-17 19:52:28.000000','Lập kế hoạch nội dung, vận hành quảng cáo và phân tích hiệu quả các kênh truyền thông số.','Hà Nội','16.000.000 - 24.000.000 VNĐ','Ngân sách chứng chỉ chuyên môn, thưởng chiến dịch, bảo hiểm và hoạt động gắn kết hàng quý.','Có kinh nghiệm quảng cáo số, phân tích dữ liệu, viết nội dung và quản lý ngân sách chiến dịch.','digital-marketing-specialist-2026','OPEN','Chuyên viên Digital Marketing','Chuyên viên (Mid-level)','Linh hoạt (Hybrid)',4,9,'NHAN_VIEN',0,6,1),(_binary '\0',2,'2026-08-25 19:52:28.000000','2026-10-14 19:52:28.000000',15,'2026-09-24 19:52:28.000000','2026-09-17 19:52:28.000000','Hạch toán nghiệp vụ, lập báo cáo định kỳ và phối hợp thực hiện các nghĩa vụ thuế của doanh nghiệp.','Đà Nẵng','18.000.000 - 26.000.000 VNĐ','Thưởng tháng mười ba, bảo hiểm đầy đủ, khám sức khỏe và hỗ trợ đào tạo nghiệp vụ thuế.','Tốt nghiệp tài chính kế toán, nắm vững chuẩn mực kế toán và sử dụng tốt phần mềm kế toán.','ke-toan-tong-hop-2026','OPEN','Kế toán Tổng hợp','Chuyên viên (Mid-level)','Toàn thời gian (Full-time)',5,10,'NHAN_VIEN',0,7,1),(_binary '\0',3,'2026-08-27 19:52:28.000000','2026-10-05 19:52:28.000000',16,'2026-09-24 19:52:28.000000','2026-09-17 19:52:28.000000','Theo dõi quy trình dịch vụ, xử lý sự cố và phối hợp các phòng ban để duy trì hoạt động ổn định.','TP. Hồ Chí Minh','16.000.000 - 22.000.000 VNĐ','Phụ cấp ăn trưa, điện thoại, thưởng chất lượng và chương trình phát triển năng lực nội bộ.','Tư duy hệ thống, xử lý vấn đề tốt, thành thạo bảng tính và có khả năng phối hợp đa phòng ban.','chuyen-vien-van-hanh-2026','PAUSED','Chuyên viên Vận hành','Nhân viên (Junior)','Toàn thời gian (Full-time)',6,11,'NHAN_VIEN',0,8,1),(_binary '\0',4,'2026-08-29 19:52:28.000000','2026-10-12 19:52:28.000000',17,'2026-09-24 19:52:28.000000','2026-09-17 19:52:28.000000','Tiếp nhận yêu cầu, hướng dẫn sử dụng sản phẩm và theo dõi mức độ hài lòng của khách hàng.','TP. Hồ Chí Minh','13.000.000 - 18.000.000 VNĐ','Phụ cấp ca làm việc, thưởng dịch vụ, bảo hiểm và đào tạo kỹ năng chăm sóc khách hàng.','Giọng nói rõ ràng, giao tiếp tích cực, kiên nhẫn và sử dụng tốt các công cụ chăm sóc khách hàng.','nhan-vien-cham-soc-khach-hang-2026','OPEN','Nhân viên Chăm sóc Khách hàng','Nhân viên (Junior)','Toàn thời gian (Full-time)',7,12,'NHAN_VIEN',0,9,1),(_binary '',1,'2026-08-31 19:52:28.000000','2026-10-19 19:52:28.000000',18,'2026-09-24 19:52:28.000000','2026-09-17 19:52:28.000000','Xây dựng lộ trình sản phẩm, quản lý backlog và phối hợp với kỹ thuật để bàn giao tính năng.','TP. Hồ Chí Minh','30.000.000 - 45.000.000 VNĐ','Quyền chọn làm việc linh hoạt, ngân sách nghiên cứu người dùng và thưởng theo kết quả sản phẩm.','Có kinh nghiệm phát triển sản phẩm số, phân tích nghiệp vụ và làm việc theo phương pháp Agile.','product-owner-2026','OPEN','Product Owner','Chuyên viên cao cấp (Senior)','Linh hoạt (Hybrid)',8,13,'NHAN_VIEN',0,10,1),(_binary '\0',2,'2026-09-02 19:52:28.000000','2026-10-07 19:52:28.000000',19,'2026-09-24 19:52:28.000000','2026-09-17 19:52:28.000000','Rà soát hợp đồng, tư vấn quy định pháp luật và theo dõi các nghĩa vụ tuân thủ của doanh nghiệp.','Hà Nội','20.000.000 - 30.000.000 VNĐ','Bảo hiểm sức khỏe, hỗ trợ chứng chỉ nghề nghiệp và ngân sách cập nhật văn bản pháp luật.','Tốt nghiệp luật, có kinh nghiệm hợp đồng thương mại và kỹ năng nghiên cứu văn bản pháp luật.','chuyen-vien-phap-che-2026','PAUSED','Chuyên viên Pháp chế','Chuyên viên (Mid-level)','Toàn thời gian (Full-time)',9,15,'NHAN_VIEN',0,11,1),(_binary '',1,'2026-09-17 20:51:16.872140','2026-09-19 20:50:00.000000',25,'2026-09-17 20:51:00.000000','2026-09-21 09:16:15.296613','Chuyên viên kĩ thuật robot ','Hồ CHí Minh','100000','Thưởng lương tháng 13','yêu cầu về AI','chuyen-vien-ai-1789653076849','EXPIRED','Chuyên Viên AI','Chuyên viên (Mid-level)','Toàn thời gian (Full-time)',1,1,'NHAN_VIEN',0,12,1),(_binary '\0',1,'2026-09-21 13:48:26.357007','2026-09-22 13:48:00.000000',26,'2026-09-21 13:48:00.000000','2026-09-23 09:03:44.932036','Lập ngân sách, quản lý dòng tiền, lập báo cáo tài chính','HCM','8.888.880 - 10.000.000 VNĐ','','Có tiếng anh','nhan-vien-tai-chinh-1789973306348','EXPIRED','Nhân viên Tài chính','Nhân viên (Junior)','Toàn thời gian (Full-time)',1,21,'NHAN_VIEN',0,13,1),(_binary '\0',1,'2026-09-23 14:08:21.737827','2026-09-24 14:08:00.000000',27,'2026-09-23 14:08:00.000000','2026-09-23 14:08:21.795481','Lập ngân sách, quản lý dòng tiền, lập báo cáo tài chính','HCM','8.888.880 - 10.000.000 VNĐ','','Có tiếng anh','nhan-vien-tai-chinh-1790147301717','OPEN','Nhân viên Tài chính','Chuyên viên (Mid-level)','Toàn thời gian (Full-time)',1,21,'NHAN_VIEN',1,14,1);
