--
-- Table structure for table `job_requisitions`
--

DROP TABLE IF EXISTS `job_requisitions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `job_requisitions` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `approver_id` bigint DEFAULT NULL,
  `budget` varchar(100) DEFAULT NULL,
  `cap_bac` varchar(100) DEFAULT NULL,
  `created_at` datetime(6) DEFAULT NULL,
  `department_id` bigint DEFAULT NULL,
  `description` text,
  `hinh_thuc_lam_viec` varchar(100) DEFAULT NULL,
  `reason` text NOT NULL,
  `rejection_reason` text,
  `requester_id` bigint NOT NULL,
  `requirements` text,
  `so_luong` int NOT NULL,
  `status` enum('DRAFT','PENDING_APPROVAL','APPROVED','REVISION_REQUIRED','REJECTED','CANCELLED','FULFILLED') NOT NULL,
  `target_role` enum('ADMIN','CEO','GIAM_DOC_PHONG_BAN','NHAN_VIEN','TRUONG_PHONG') NOT NULL,
  `title` varchar(150) NOT NULL,
  `updated_at` datetime(6) DEFAULT NULL,
  `version` bigint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=22 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

