INSERT INTO `performance_reviews` VALUES (1,'Dưới đây là báo cáo đánh giá hiệu suất nhân sự dựa trên dữ liệu chấm công tháng 09/2026:\n\n### BÁO CÁO ĐÁNH GIÁ HIỆU SUẤT CHẤM CÔNG - THÁNG 09/2026\n\n**1. Tổng quan**\nTrong tháng 09/2026, hệ thống ghi nhận tổng số ngày có dữ liệu chấm công của nhân sự là **0 ngày**. Nhân sự không phát sinh bất kỳ bản ghi chấm công nào trong toàn bộ chu kỳ tính lương tháng.\n\n**2. Điểm đáng chú ý**\n*   Số ngày đi muộn: 0\n*   Số ngày vắng mặt/nghỉ có phép hoặc không phép: 0\n*   *Nhận xét:* Dữ liệu cho thấy sự vắng bóng hoàn toàn của các bản ghi thời gian làm việc. Không ghi nhận tình trạng vi phạm kỷ luật giờ giấc (đi muộn), tuy nhiên cũng không có dữ liệu xác thực ngày công thực tế tại văn phòng/hệ thống.\n\n**3. Khuyến nghị**\n*   Yêu cầu nhân sự ngay lập tức làm việc trực tiếp với bộ phận Nhân sự (HR) và Quản lý trực tiếp để rà soát lại trạng thái lao động trong tháng 09/2026 (có thể do lỗi thiết bị chấm công, quên checkout, nghỉ việc chưa hoàn tất thủ tục, hoặc chưa cập nhật hợp đồng).\n*   Đề nghị Quản lý trực tiếp kiểm tra lại tiến độ công việc thực tế của nhân sự này trong tháng qua để đảm bảo không có sự gián đoạn trong vận hành.\n\n--- \n*Lưu ý: Báo cáo này hoàn toàn dựa trên dữ liệu hệ thống ghi nhận tính đến thời điểm hiện tại và sẽ được điều chỉnh sau khi có giải trình chính thức.*',3,'2026-09-17 13:56:03.607524',2026,9),(2,'Dưới đây là Báo cáo đánh giá hiệu suất tháng 9/2027 dựa trên dữ liệu chấm công được cung cấp:\n\n### **BÁO CÁO ĐÁNH GIÁ HIỆU SUẤT THÁNG 9/2027**\n\n**Tổng quan**\nTrong tháng 9/2027, hệ thống ghi nhận dữ liệu chấm công của nhân sự đạt **0 ngày**. Do hoàn toàn thiếu dữ liệu chuyên cần, phòng Nhân sự không có cơ sở để đánh giá ngày công thực tế, tình trạng đi muộn (0 ngày) hay vắng mặt (0 ngày) theo cách hiểu thông thường.\n\n**Điểm đáng chú ý**\n* **Vấn đề dữ liệu:** Việc không có bất kỳ bản ghi chấm công nào trong cả tháng là một bất thường lớn trong quy trình quản trị nhân sự. \n* **Rủi ro vận hành:** Tình trạng này có thể xuất phát từ lỗi hệ thống kỹ thuật, sự cố thiết bị chấm công, hoặc nhân sự chưa tuân thủ quy trình chấm công bắt buộc của công ty.\n\n**Khuyến nghị**\n1. **Đối với Nhân sự:** Yêu cầu nhân viên ngay lập tức liên hệ với bộ phận HR và IT trong vòng 24 giờ tới để giải trình lý do không có dữ liệu chấm công và tiến hành bổ sung thủ tục xác nhận công tháng 9 (nếu có làm việc thực tế).\n2. **Đối vơi Bộ phận HR:** Kiểm tra lại hệ thống ghi nhận chấm công để loại trừ khả năng lỗi kỹ thuật từ phía công ty. \n3. **Lưu ý:** Nếu việc không chấm công xuất phát từ nguyên quan chủ quan (quên chấm công, tự ý nghỉ không phép), nhân sự sẽ phải chịu hình thức kỷ luật tương ứng theo nội quy công ty. Đề nghị nghiêm túc rút kinh nghiệm và tuân thủ nghiêm ngặt quy định chấm công từ tháng tiếp theo.',3,'2026-09-17 13:56:44.464380',2027,9),(3,'Dưới đây là Báo cáo đánh giá hiệu suất nhân sự tháng 09/2026 dựa trên dữ liệu chấm công được cung cấp:\n\n***\n\n# BÁO CÁO ĐÁNH GIÁ HIỆU SUẤT THÁNG 09/2026\n\n### Tổng quan\nDữ liệu chấm công tháng 09/2026 ghi nhận tổng số ngày có dữ liệu của nhân viên là **0 ngày**. Không có dữ liệu về việc đi muộn hay vắng mặt/nghỉ phép được ghi nhận trong hệ thống.\n\n### Điểm đáng chú ý\n* **Sự bất thường trong dữ liệu:** Việc không có bất kỳ dữ liệu chấm công nào trong cả tháng (0 ngày) là một vấn đề nghiêm trọng cần được làm rõ ngay lập tức. \n* Tình trạng này có thể xuất phát từ lỗi kỹ thuật của hệ thống, nhân viên quên chấm công, hoặc nhân viên đã nghỉ việc/chuyển trạng thái công tác nhưng chưa được cập nhật trên hệ thống HR.\n\n### Khuyến nghị\n1. **Đối với Nhân sự (HR):** Cần phối hợp ngay với bộ phận IT hoặc Quản lý trực tiếp để kiểm tra lại tình trạng hoạt động của hệ thống chấm công và xác thực trạng thái lao động hiện tại của nhân viên này.\n2. **Đối với Nhân viên:** Yêu cầu nhân viên liên hệ gấp với phòng HR để giải trình về tình trạng vắng mặt dữ liệu trong suốt tháng 09/2026. Nếu có sai sót từ phía cá nhân, nhân viên cần nghiêm túc chấn chỉnh và tuân thủ chặt chẽ quy định chấm công từ tháng tiếp theo. \n\n*Báo cáo này mang tính chất xác minh dữ liệu hành chính và sẽ được điều chỉnh sau khi có kết quả giải trình chính thức.*',1,'2026-09-17 13:58:01.688978',2026,9),(4,'Hoàn thành tốt kế hoạch doanh thu, duy trì tỷ lệ chuyển đổi ổn định và hỗ trợ đội ngũ xử lý các cơ hội lớn. Nên tiếp tục chuẩn hóa quy trình dự báo doanh số.',8,'2026-09-17 19:52:28.000000',2026,9),(5,'Triển khai đúng tiến độ các chiến dịch trọng điểm, kiểm soát ngân sách tốt và cải thiện chất lượng khách hàng tiềm năng. Cần tăng cường đo lường đóng góp theo kênh.',11,'2026-09-17 19:52:28.000000',2026,9),(6,'Bảo đảm báo cáo tài chính đúng hạn, quản lý dòng tiền chặt chẽ và chủ động cảnh báo rủi ro ngân sách. Nên tiếp tục tự động hóa công tác đối soát.',15,'2026-09-17 19:52:28.000000',2026,9),(7,'Dẫn dắt nhóm kinh doanh đạt tiến độ, theo sát dữ liệu khách hàng và hỗ trợ nhân viên mới hiệu quả. Cần cải thiện độ chính xác của dự báo theo tuần.',7,'2026-09-17 19:52:28.000000',2026,9),(8,'Quản lý nội dung và quảng cáo nhất quán, phối hợp tốt với kinh doanh và giữ đúng cam kết tiến độ. Nên thử nghiệm thêm các kênh tăng trưởng mới.',12,'2026-09-17 19:52:28.000000',2026,9),(9,'Kiểm soát chứng từ cẩn thận, hoàn thành nghĩa vụ thuế đúng hạn và hỗ trợ tốt công tác kiểm toán. Cần xây dựng thêm bộ chỉ số cảnh báo sớm.',13,'2026-09-17 19:52:28.000000',2026,9),(10,'Duy trì hoạt động ổn định, phản hồi nhanh với sự cố và phối hợp hiệu quả giữa các phòng ban. Nên cập nhật tài liệu quy trình sau mỗi thay đổi.',16,'2026-09-17 19:52:28.000000',2026,9),(11,'Duy trì chất lượng phản hồi khách hàng, xử lý khiếu nại tích cực và hỗ trợ đào tạo nhân viên. Cần giảm thời gian xử lý các yêu cầu phức tạp.',17,'2026-09-17 19:52:28.000000',2026,9),(12,'Xác định ưu tiên sản phẩm rõ ràng, phối hợp tốt với kỹ thuật và sử dụng phản hồi người dùng trong quyết định. Nên tăng tần suất theo dõi chỉ số sau phát hành.',18,'2026-09-17 19:52:28.000000',2026,9),(19,'**BÁO CÁO ĐÁNH GIÁ HIỆU SUẤT THÁNG 9/2026**\n\n**1. Tổng quan**\nTrong tháng 9/2026, hệ thống ghi nhận dữ liệu chấm công của nhân sự trong 3 ngày làm việc. Nhân sự duy trì tốt tinh thần kỷ luật chuyên cần với tỷ lệ có mặt đạt 100%, không ghi nhận trường hợp vắng mặt hay nghỉ phép nào trong giai đoạn này.\n\n**2. Điểm đáng chú ý**\nMặc dù không có ngày vắng mặt, dữ liệu ghi nhận tình trạng đi muộn 3/3 ngày (tỷ lệ 100% số ngày có dữ liệu). Vấn đề này ảnh hưởng trực tiếp đến tác phong làm việc chuyên nghiệp, tuân thủ nội quy công ty và có thể tác động tiêu cực đến tiến độ công việc chung cũng như hiệu suất tổng thể.\n\n**3. Khuyến nghị**\n*   Yêu cầu nhân sự nghiêm túc chấn chỉnh lại tác phong giờ giấc làm việc, tuân thủ tuyệt đối nội quy công ty về thời gian bắt đầu làm việc trong các tháng tiếp theo.\n*   Bộ phận Nhân sự và Quản lý trực tiếp sẽ tiếp tục theo dõi sát sao biểu đồ chấm công. Trường hợp tình trạng đi muộn vẫn tiếp diễn, chúng tôi sẽ áp dụng các biện pháp xử lý theo đúng quy chế kỷ luật lao động hiện hành. \n\n*Chân thành ghi nhận nỗ lực chuyên cần của nhân sự và kỳ vọng sự cải thiện rõ rệt về ý thức thời gian trong thời gian tới.*',2,'2026-09-22 14:13:10.673723',2026,9),(20,'Dưới đây là báo cáo đánh giá hiệu suất nhân sự tháng 12/2026 dựa trên dữ liệu thực tế:\n\n***\n\n# BÁO CÁO ĐÁNH GIÁ HIỆU SUẤT THÁNG 12/2026\n\n**Nhân sự:** [Họ và Tên Nhân Viên]  \n**Bộ phận:** [Tên Bộ Phận]  \n\n### 1. Tổng quan\nDữ liệu chấm công tháng 12/2026 ghi nhận **0 ngày** có dữ liệu, không có ghi nhận về việc đi muộn hay vắng mặt/nghỉ phép.\n\n### 2. Điểm đáng chú ý\nDo hoàn toàn không có dữ liệu chấm công trên hệ thống trong suốt tháng 12/2026, phòng Nhân sự không có cơ sở để đánh giá ngày công, mức độ chuyên cần cũng như hiệu suất công việc thực tế của nhân sự trong kỳ này. \n\n### 3. Khuyến nghị\n* **Yêu cầu nhân sự:** Chủ động liên hệ ngay với bộ phận Nhân sự và Quản lý trực tiếp trong vòng 24 giờ để làm rõ nguyên nhân thiếu dữ liệu chấm công (lỗi hệ thống, quên chấm công, hoặc trạng thái công việc chưa được cập nhật).\n* **Quản lý trực tiếp:** Tiến hành rà soát lại kết quả công việc thực tế của nhân sự trong tháng 12/2026 để có căn cứ bổ sung bảng lương và đưa ra đánh giá chính xác, tránh ảnh hưởng đến quyền lợi và kỷ luật lao động chung.',3,'2026-09-22 14:14:00.650363',2026,12);
