INSERT INTO `screening_criteria_sets` VALUES (1,9,1,'CONFIRMED','{\"level\": \"Nhân viên (Junior)\", \"title\": \"Chuyên viên phân tích\", \"source\": \"LEGACY_JD_SNAPSHOT\", \"description\": \"Là 1 chuyên viên phân tích dữ liệu dựa trên hình ảnh\", \"requirements\": \"Có kinh nghiệm\"}','34afebfe93d8e6422af3fae9d80b4ab9b3997e37fee6583240c6fae6e5abd5f2',NULL,NULL,'Backfill posting có trước Chặng 2','2026-09-17 14:54:52.839019','2026-09-23 14:41:15.343597'),(2,10,1,'CONFIRMED','{\"level\": \"Chuyên viên (Mid-level)\", \"title\": \"Chuyên viên Tuyển dụng\", \"source\": \"LEGACY_JD_SNAPSHOT\", \"description\": \"Phụ trách toàn bộ quy trình tìm nguồn, sàng lọc, phỏng vấn và chăm sóc ứng viên.\", \"requirements\": \"Có tối thiểu hai năm kinh nghiệm tuyển dụng, giao tiếp tốt và sử dụng thành thạo công cụ quản lý hồ sơ.\"}','a63af63241376fb7fa4d36bfeafafe4dd4a287459428e8a0a36940e640c77727',NULL,NULL,'Backfill posting có trước Chặng 2','2026-08-16 19:52:28.000000','2026-09-23 14:41:15.343597'),(3,11,1,'CONFIRMED','{\"level\": \"Chuyên viên (Mid-level)\", \"title\": \"Lập trình viên Backend\", \"source\": \"LEGACY_JD_SNAPSHOT\", \"description\": \"Phát triển API, tối ưu truy vấn dữ liệu và bảo đảm an toàn cho các dịch vụ backend.\", \"requirements\": \"Thành thạo Java, Spring Boot, MySQL, REST API và có kinh nghiệm viết kiểm thử tự động.\"}','00a1bcf482b0fa75a983962cc3c85836252cbf1d7a50dd72a2386c758c9c0489',NULL,NULL,'Backfill posting có trước Chặng 2','2026-08-18 19:52:28.000000','2026-09-23 14:41:15.343597'),(4,12,1,'CONFIRMED','{\"level\": \"Nhân viên (Junior)\", \"title\": \"Chuyên viên Kinh doanh B2B\", \"source\": \"LEGACY_JD_SNAPSHOT\", \"description\": \"Tìm kiếm khách hàng doanh nghiệp, tư vấn giải pháp và theo dõi cơ hội bán hàng đến khi ký hợp đồng.\", \"requirements\": \"Có kỹ năng giao tiếp, đàm phán, quản lý cơ hội bán hàng và chủ động đạt mục tiêu doanh số.\"}','c2a41a0926340b10b6e91f441907a43f30bf571eade2d1682b83fa8d1edd453d',NULL,NULL,'Backfill posting có trước Chặng 2','2026-08-21 19:52:28.000000','2026-09-23 14:41:15.343597'),(5,13,1,'CONFIRMED','{\"level\": \"Quản lý (Manager)\", \"title\": \"Trưởng nhóm Kinh doanh\", \"source\": \"LEGACY_JD_SNAPSHOT\", \"description\": \"Quản lý nhóm bán hàng, huấn luyện nhân viên và chịu trách nhiệm về kế hoạch doanh thu khu vực.\", \"requirements\": \"Có tối thiểu ba năm quản lý bán hàng B2B, kỹ năng huấn luyện và lập kế hoạch doanh số.\"}','d20bf2126c9ef09cc0e8defb24592afdabf5a2302a3e85a841b3b75fa45952a1',NULL,NULL,'Backfill posting có trước Chặng 2','2026-09-06 19:52:28.000000','2026-09-23 14:41:15.343597'),(6,14,1,'CONFIRMED','{\"level\": \"Chuyên viên (Mid-level)\", \"title\": \"Chuyên viên Digital Marketing\", \"source\": \"LEGACY_JD_SNAPSHOT\", \"description\": \"Lập kế hoạch nội dung, vận hành quảng cáo và phân tích hiệu quả các kênh truyền thông số.\", \"requirements\": \"Có kinh nghiệm quảng cáo số, phân tích dữ liệu, viết nội dung và quản lý ngân sách chiến dịch.\"}','8ee4e776df8e5aebc7fe65d25efcd61400f4f30e4ae2718f5382c26d3cf65adf',NULL,NULL,'Backfill posting có trước Chặng 2','2026-08-23 19:52:28.000000','2026-09-23 14:41:15.343597'),(7,15,1,'CONFIRMED','{\"level\": \"Chuyên viên (Mid-level)\", \"title\": \"Kế toán Tổng hợp\", \"source\": \"LEGACY_JD_SNAPSHOT\", \"description\": \"Hạch toán nghiệp vụ, lập báo cáo định kỳ và phối hợp thực hiện các nghĩa vụ thuế của doanh nghiệp.\", \"requirements\": \"Tốt nghiệp tài chính kế toán, nắm vững chuẩn mực kế toán và sử dụng tốt phần mềm kế toán.\"}','6cc430a070b9bc9e54e4efc60c7e03e7be84f2e17274ac24b1c4c11fbcc12fd5',NULL,NULL,'Backfill posting có trước Chặng 2','2026-08-25 19:52:28.000000','2026-09-23 14:41:15.343597'),(8,16,1,'CONFIRMED','{\"level\": \"Nhân viên (Junior)\", \"title\": \"Chuyên viên Vận hành\", \"source\": \"LEGACY_JD_SNAPSHOT\", \"description\": \"Theo dõi quy trình dịch vụ, xử lý sự cố và phối hợp các phòng ban để duy trì hoạt động ổn định.\", \"requirements\": \"Tư duy hệ thống, xử lý vấn đề tốt, thành thạo bảng tính và có khả năng phối hợp đa phòng ban.\"}','fc7f41290004bb68699b0dc0e6a814d1a9778eea96e120e4bb5b7e67e00e9417',NULL,NULL,'Backfill posting có trước Chặng 2','2026-08-27 19:52:28.000000','2026-09-23 14:41:15.343597'),(9,17,1,'CONFIRMED','{\"level\": \"Nhân viên (Junior)\", \"title\": \"Nhân viên Chăm sóc Khách hàng\", \"source\": \"LEGACY_JD_SNAPSHOT\", \"description\": \"Tiếp nhận yêu cầu, hướng dẫn sử dụng sản phẩm và theo dõi mức độ hài lòng của khách hàng.\", \"requirements\": \"Giọng nói rõ ràng, giao tiếp tích cực, kiên nhẫn và sử dụng tốt các công cụ chăm sóc khách hàng.\"}','077935c5999f24b7f5526549b4cb88cc77596df9d5f7491595b786b8f2e57053',NULL,NULL,'Backfill posting có trước Chặng 2','2026-08-29 19:52:28.000000','2026-09-23 14:41:15.343597'),(10,18,1,'CONFIRMED','{\"level\": \"Chuyên viên cao cấp (Senior)\", \"title\": \"Product Owner\", \"source\": \"LEGACY_JD_SNAPSHOT\", \"description\": \"Xây dựng lộ trình sản phẩm, quản lý backlog và phối hợp với kỹ thuật để bàn giao tính năng.\", \"requirements\": \"Có kinh nghiệm phát triển sản phẩm số, phân tích nghiệp vụ và làm việc theo phương pháp Agile.\"}','87efc02e57420c1b0832f6ceed7b8763a2c08111c860b0975a4f0862eec2484b',NULL,NULL,'Backfill posting có trước Chặng 2','2026-08-31 19:52:28.000000','2026-09-23 14:41:15.343597'),(11,19,1,'CONFIRMED','{\"level\": \"Chuyên viên (Mid-level)\", \"title\": \"Chuyên viên Pháp chế\", \"source\": \"LEGACY_JD_SNAPSHOT\", \"description\": \"Rà soát hợp đồng, tư vấn quy định pháp luật và theo dõi các nghĩa vụ tuân thủ của doanh nghiệp.\", \"requirements\": \"Tốt nghiệp luật, có kinh nghiệm hợp đồng thương mại và kỹ năng nghiên cứu văn bản pháp luật.\"}','7d2e1a388adb4136c20f3547106e7a90a01ce413b048750ce72caecc774d7afb',NULL,NULL,'Backfill posting có trước Chặng 2','2026-09-02 19:52:28.000000','2026-09-23 14:41:15.343597'),(12,25,1,'CONFIRMED','{\"level\": \"Chuyên viên (Mid-level)\", \"title\": \"Chuyên Viên AI\", \"source\": \"LEGACY_JD_SNAPSHOT\", \"description\": \"Chuyên viên kĩ thuật robot \", \"requirements\": \"yêu cầu về AI\"}','c74f4fcabef78825f0c497d6ab6d00848879d6e76d10d57a982e22275be982af',NULL,NULL,'Backfill posting có trước Chặng 2','2026-09-17 20:51:16.872140','2026-09-23 14:41:15.343597'),(13,26,1,'CONFIRMED','{\"level\": \"Nhân viên (Junior)\", \"title\": \"Nhân viên Tài chính\", \"source\": \"LEGACY_JD_SNAPSHOT\", \"description\": \"Lập ngân sách, quản lý dòng tiền, lập báo cáo tài chính\", \"requirements\": \"Có tiếng anh\"}','ce9b8da66b56fa4aa84d4634c910ec5d80d2134d25ee53eaf146e43c71c468c2',NULL,NULL,'Backfill posting có trước Chặng 2','2026-09-21 13:48:26.357007','2026-09-23 14:41:15.343597'),(14,27,1,'CONFIRMED','{\"level\": \"Chuyên viên (Mid-level)\", \"title\": \"Nhân viên Tài chính\", \"source\": \"LEGACY_JD_SNAPSHOT\", \"description\": \"Lập ngân sách, quản lý dòng tiền, lập báo cáo tài chính\", \"requirements\": \"Có tiếng anh\"}','e16a41eb64c8c8739f0e76865facc750ddbb1ad34bcad4971a478fb6a6b50205',NULL,NULL,'Backfill posting có trước Chặng 2','2026-09-23 14:08:21.737827','2026-09-23 14:41:15.343597');
